  2039  static int sam_hdr_link_pg(sam_hdr_t *bh) {
  2040      sam_hrecs_t *hrecs;
  2041      int i, j, ret = 0, *new_pg_end;
  2042
  2043      if (!bh)
  2044          return -1;
  2045
  2046      if (!(hrecs = bh->hrecs)) {
  2047          if (sam_hdr_fill_hrecs(bh) != 0)
  2048              return -1;
  2049          hrecs = bh->hrecs;
  2050      }
  2051
  2052      if (!hrecs->pgs_changed || !hrecs->npg)
  2053          return 0;
  2054
  2055      hrecs->npg_end_alloc = hrecs->npg;
  2056      new_pg_end = realloc(hrecs->pg_end, hrecs->npg * sizeof(*new_pg_end));
  2057      if (!new_pg_end)
  2058          return -1;
  2059      hrecs->pg_end = new_pg_end;
  2060      int *chain_size = calloc(hrecs->npg, sizeof(int));
  2061      if (!chain_size)
  2062          return -1;
  2063
  2064      for (i = 0; i < hrecs->npg; i++)
  2065          hrecs->pg_end[i] = i;
  2066
  2067      for (i = 0; i < hrecs->npg; i++) {
  2068          khint_t k;
  2069          sam_hrec_tag_t *tag;
  2070
  2071          assert(hrecs->pg[i].ty != NULL);
  2072          for (tag = hrecs->pg[i].ty->tag; tag; tag = tag->next) {
  2073              if (tag->str[0] == 'P' && tag->str[1] == 'P')
  2074                  break;
  2075          }
  2076          if (!tag) {
  2077              /* Chain start points */
  2078              continue;
  2079          }
  2080
  2081          k = kh_get(m_s2i, hrecs->pg_hash, tag->str+3);
  2082
  2083          if (k == kh_end(hrecs->pg_hash)) {
  2084              ret = -1;
  2085              continue;
  2086          }
  2087
  2088          hrecs->pg[i].prev_id = hrecs->pg[kh_val(hrecs->pg_hash, k)].id;
  2089          hrecs->pg_end[kh_val(hrecs->pg_hash, k)] = -1;
  2090          chain_size[i] = chain_size[kh_val(hrecs->pg_hash, k)]+1;
  2091      }
  2092
  2093      for (i = j = 0; i < hrecs->npg; i++) {
  2094          if (hrecs->pg_end[i] != -1 && chain_size[i] > 0)
  2095              hrecs->pg_end[j++] = hrecs->pg_end[i];
  2096      }
  2097      /* Only leafs? Choose the last one! */
  2098      if (!j && hrecs->npg_end > 0) {
  2099          hrecs->pg_end[0] = hrecs->pg_end[hrecs->npg_end-1];
  2100          j = 1;
  2101      }
